import getpass, os, sys, urllib.error, urllib.request
from telegram_transport import open_telegram, parse_proxy, ProxyTransportError

def main():
    print("Bot API uses HTTPS; TGWS MTProto 127.0.0.1:1443 is NOT an HTTP CONNECT/SOCKS5 proxy.")
    print("Use a real HTTP CONNECT or SOCKS5h proxy URL; leave empty to test direct access.")
    entered=getpass.getpass("HTTP/SOCKS5h proxy URL (hidden, optional): ").strip()
    try:parse_proxy(entered)
    except ProxyTransportError as e:
        print("PROXY_INVALID:"+str(e));return 2
    req=urllib.request.Request("https://api.telegram.org/")
    try:
        with open_telegram(req,proxy=entered,timeout=8) as r:
            print("TELEGRAM_BOT_API_TRANSPORT_REACHABLE; HTTPS status="+str(r.status))
        return 0
    except urllib.error.HTTPError as e:
        # An HTTP status proves HTTPS routing succeeded even if root endpoint doesn't exist.
        print("TELEGRAM_BOT_API_TRANSPORT_REACHABLE; HTTPS status="+str(e.code))
        return 0
    except ProxyTransportError as e:
        print("PROXY_REJECTED:"+str(e));return 2
    except (OSError,urllib.error.URLError,TimeoutError) as e:
        print("HTTPS_CONNECTIVITY_FAILED:"+type(e).__name__);return 2

if __name__=="__main__":sys.exit(main())
